#!/bin/bash
# Flight Deck Desk installer (vcge-lab PR #1, commit fcf40e0). Written by Cornerstone (Team vCGE) 2026-10-26.
# What it does, and nothing else:
#  1. Checks the files packed below against their sha256; stops if anything changed since review.
#  2. Checks the live Flight Deck index.html and portal.css are still the reviewed versions (vcge-lab main e21e5b3);
#     stops without changing anything if they are not.
#  3. Backs up the live Flight Deck folder to portal/www.before-desk.
#  4. Adds portal/www/desk/ (Rules, Welcome, Copy-paste Inbox + config.js with the Google Client ID) and the new
#     index.html and portal.css (three Desk tiles, honest "only the Desk talks to Google" wording). Root-owned, 644.
#  5. Checks http://127.0.0.1:8080/ and /desk/ answer 200. No Caddy change, no service change, no reload.
# Undo: sudo rm -rf /srv/dataprojects/portal/www && sudo cp -a /srv/dataprojects/portal/www.before-desk /srv/dataprojects/portal/www
set -euo pipefail
WWW=/srv/dataprojects/portal/www
PAYLOAD_SHA=137a5da8794e160058a608aeea933ca670feec89706870678d98a482f5301699
OLD_INDEX_SHA=561fac12704b4c94fb9f208c34f7ff0d0076567cf342d0859b908aee022f9747
OLD_CSS_SHA=54d1b12d239fd8c7d7e93837f6973136a010b17624a6b321df612ea2ee0b3e7e
[ "$(id -u)" = 0 ] || { echo "Run through vcge-lab-run (needs root)."; exit 1; }
[ -d "$WWW" ] || { echo "STOP: $WWW not found. Nothing changed."; exit 1; }
TMP=$(mktemp -d); trap 'rm -rf "$TMP"' EXIT
base64 -d > "$TMP/payload.tgz" <<'PAYLOAD'

PAYLOAD
echo "$PAYLOAD_SHA  $TMP/payload.tgz" | sha256sum -c --quiet - || { echo "STOP: packed files changed since review. Nothing changed."; exit 1; }
echo "$OLD_INDEX_SHA  $WWW/index.html" | sha256sum -c --quiet - || { echo "STOP: live index.html is not the reviewed version. Nothing changed."; exit 1; }
echo "$OLD_CSS_SHA  $WWW/portal.css" | sha256sum -c --quiet - || { echo "STOP: live portal.css is not the reviewed version. Nothing changed."; exit 1; }
[ -e "$WWW.before-desk" ] && { echo "STOP: backup $WWW.before-desk already exists (installed before?). Nothing changed."; exit 1; }
cp -a "$WWW" "$WWW.before-desk"
mkdir "$TMP/x"; tar -xzf "$TMP/payload.tgz" -C "$TMP/x" --no-same-owner
install -d -o root -g root -m 755 "$WWW/desk"
for f in desk/index.html desk/desk.js desk/desk-core.js desk/desk.css desk/config.js index.html portal.css; do
  install -o root -g root -m 644 "$TMP/x/$f" "$WWW/$f"
done
for p in / /desk/ /desk/desk.js /desk/config.js; do
  code=$(curl -s -o /dev/null -w '%{http_code}' "http://127.0.0.1:8080$p")
  echo "$p -> $code"; [ "$code" = 200 ] || { echo "CHECK FAILED on $p. Undo line is at the top of this script."; exit 1; }
done
echo "Desk installed. Open https://vcge-lab.tailfc4090.ts.net/desk/ . Backup: $WWW.before-desk"
